mockups.css:
:root{--ink:#1e2e27;--ink-soft:#5c7069;--paper:#fff;--cream:#f4f8f0;--stage:#edf1ea;--line:#e2eadf;--line-strong:#cbdac7;--mint:#1b8168;--primary-soft:#dcf5ec;--accent:#a9c24f;--accent-soft:#eaf2ce;--teal-soft:#d9ecec;--danger:#b23b3b;--danger-soft:#f6e4e2;--scrim:rgb(20 28 24/.55)}
*{box-sizing:border-box}
body{font-family:Figtree,'Segoe UI',system-ui,sans-serif;color:var(--ink);background:var(--stage);margin:0}
.stage{display:flex;justify-content:center;padding:24px 16px}
.phone{position:relative;width:390px;min-height:760px;background:var(--cream);border-radius:34px;border:1px solid var(--line-strong);overflow:hidden;display:flex;flex-direction:column}
.content{flex:1;padding:18px 18px 24px}
.back{font-size:13px;color:var(--ink-soft);font-weight:700;margin-bottom:10px}
h2{font-family:'Bricolage Grotesque','Segoe UI',sans-serif;font-size:19px;font-weight:600;margin:0}
h3.sheet-title{font-family:'Bricolage Grotesque','Segoe UI',sans-serif;font-size:18px;font-weight:600;margin:0}
.card{margin-top:16px;border:1px solid var(--line);background:var(--paper);border-radius:22px;padding:20px}
.field{display:flex;flex-direction:column;gap:6px;margin-bottom:12px}
.label{font-size:12px;font-weight:800;letter-spacing:.02em;color:var(--ink-soft)}
.req{color:var(--danger)}
.input{border:1.5px solid var(--line);background:var(--cream);border-radius:12px;padding:10px 14px;font-size:14px;color:var(--ink)}
.input.placeholder{color:var(--ink-soft)}
.picker-btn{display:flex;align-items:center;justify-content:space-between;cursor:pointer;text-align:left}
.picker-btn .path{font-size:12px;color:var(--ink-soft)}
.picker-btn .leaf{font-weight:700}
.chev{color:var(--ink-soft);font-size:16px}
.hint{font-size:11.5px;color:var(--ink-soft);margin-top:6px}
.photo-drop{border:1.5px dashed var(--line-strong);border-radius:14px;padding:14px;text-align:center;font-size:13px;color:var(--ink-soft);margin-top:8px}
.alert{border-radius:12px;background:var(--danger-soft);color:var(--danger);font-size:13px;padding:10px 12px;margin-top:12px}
.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:16px}
.btn{border:0;border-radius:13px;padding:12px 16px;font-size:13.5px;font-weight:800;cursor:pointer}
.btn-primary{background:var(--mint);color:#fff}
.btn-secondary{background:var(--teal-soft);color:#244647}
.btn-ghost{grid-column:1/-1;background:transparent;border:1.5px solid var(--line-strong);color:var(--ink)}
.btn[disabled]{opacity:.6}
.scrim{position:absolute;inset:0;background:var(--scrim);display:flex;align-items:flex-end}
.sheet{width:100%;max-height:88%;background:var(--paper);border-radius:24px 24px 0 0;padding:20px;display:flex;flex-direction:column}
.sheet-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}
.close{width:36px;height:36px;border-radius:999px;background:var(--cream);display:flex;align-items:center;justify-content:center;color:var(--ink-soft)}
.search{display:flex;align-items:center;gap:8px;border:1.5px solid var(--line);background:var(--cream);border-radius:12px;padding:10px 12px;font-size:14px}
.search.focus{border-color:var(--mint)}
.crumbs{display:flex;flex-wrap:wrap;gap:4px;align-items:center;font-size:12.5px;color:var(--ink-soft);margin:14px 0 8px}
.crumbs b{color:var(--ink)}
.backlink{font-size:13px;font-weight:700;color:var(--mint);margin:12px 0 4px}
.list{list-style:none;margin:0;padding:0;overflow-y:auto}
.list li{display:flex;align-items:center;justify-content:space-between;padding:13px 4px;border-bottom:1px solid var(--line);font-size:14.5px;cursor:pointer}
.list li .sub{font-size:12px;color:var(--ink-soft)}
.list li.selected{background:var(--primary-soft);border-radius:10px;padding-inline:10px;font-weight:700}
.list li.active-desc{outline:2px solid var(--mint);border-radius:10px;padding-inline:10px}
.result-path{font-size:12px;color:var(--ink-soft)}
.result-name{font-weight:700}
mark{background:var(--accent-soft);color:inherit;border-radius:3px}
.count{font-size:12px;color:var(--ink-soft);margin:10px 0 2px}
.chip{display:inline-block;font-size:11px;font-weight:800;border-radius:6px;padding:2px 7px;background:var(--primary-soft);color:var(--mint)}
.chip.draft{background:var(--cream);color:var(--ink-soft);border:1px solid var(--line-strong)}
.item-row{display:flex;gap:12px;align-items:center}
.thumb{width:56px;height:56px;border-radius:14px;background:var(--teal-soft)}
.inline-actions{display:flex;gap:8px;margin-top:12px}
.needed li{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid var(--line);font-size:14px}
.row-add{display:flex;gap:8px}
.row-add .input{flex:1}
.btn-sm{padding:10px 14px;border-radius:12px}
/* admin (Chakra-like desktop) */
.admin{max-width:980px;margin:24px auto;background:#fff;border-radius:12px;border:1px solid #e2e8f0;padding:24px;font-size:14px;color:#1e293b}
.admin h1{font-size:22px;margin:0}
.admin-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}
.cbtn{border:1px solid #cbd5e1;background:#fff;border-radius:6px;padding:5px 10px;font-size:12.5px;cursor:pointer;color:#334155}
.cbtn.primary{background:var(--mint);color:#fff;border-color:var(--mint);font-weight:700;padding:8px 14px;font-size:13.5px}
.cbtn.danger{color:var(--danger);border-color:#f0c9c6}
.tree{list-style:none;margin:0;padding:0}
.tree li{border-bottom:1px solid #f1f5f9}
.node{display:flex;align-items:center;gap:8px;padding:8px 6px}
.node:hover{background:#f8fafc}
.toggle{width:22px;color:#64748b;text-align:center}
.nname{flex:1;font-weight:500}
.meta{font-size:12px;color:#64748b;min-width:120px}
.nactions{display:flex;gap:6px}
.lvl1{padding-left:28px}.lvl2{padding-left:56px}.lvl3{padding-left:84px}
.admin .alert{margin:0 0 14px}
.admin-filter{display:flex;gap:8px;margin-bottom:12px}
.admin-filter .input{flex:1;background:#fff;border-color:#cbd5e1}
.form-grid{display:flex;flex-direction:column;gap:14px;max-width:520px}
.form-grid .input{background:#fff;border-color:#cbd5e1}

